Tengo este servicio de TypeScript que está tardando 3-4 segundos en responder cuando hay más de 50 usuarios. Analiza qué está pasando y dame las correcciones concretas con código.

async getOrdersWithDetails(tenantId: string) {
  const orders = await this.orderRepo.find({ where: { tenantId } });
  for (const order of orders) {
    order.customer = await this.customerRepo.findOne({ where: { id: order.customerId } });
    order.items = await this.itemRepo.find({ where: { orderId: order.id } });
  }
  return orders;
}
